<?php require_once '../config/helpers.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['booking_id']??0);$status=$_POST['status']??'';$allowed=['Pending','Confirmed','Rejected','Completed','Cancelled'];if(in_array($status,$allowed,true)){$st=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?');$st->execute([$status,$id]);flash('Booking status updated.');}redirect('bookings.php');}$rows=$pdo->query('SELECT b.*,c.full_name,c.email,c.phone,s.name service_name FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN services s ON s.id=b.service_id ORDER BY b.event_date DESC,b.event_time DESC')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>All Bookings</title></head><body><div class="admin-layout"><?php include '_nav.php'; ?><section class="admin-main"><h1>All Customer Bookings</h1><?php show_flash(); ?><div class="panel table-wrap"><table class="table"><thead><tr><th>Customer details</th><th>Service</th><th>Event date & time</th><th>Location / address</th><th>Notes</th><th>Status / action</th></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td><strong><?= e($b['full_name']) ?></strong><br><?= e($b['phone']) ?><br><span class="small muted"><?= e($b['email']) ?></span></td><td><?= e($b['service_name']) ?></td><td><?= e($b['event_date']) ?><br><?= e(date('h:i A',strtotime($b['event_time']))) ?></td><td><?= e($b['event_location']) ?><br><?= e($b['full_address']) ?></td><td><?= e($b['notes']) ?></td><td><span class="badge <?= e($b['status']) ?>"><?= e($b['status']) ?></span><form method="post" class="form" style="margin-top:8px;gap:6px"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="booking_id" value="<?= (int)$b['id'] ?>"><select name="status"><?php foreach(['Pending','Confirmed','Rejected','Completed','Cancelled'] as $s): ?><option <?= $b['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button>Update</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">No bookings found.</td></tr><?php endif; ?></tbody></table></div></section></div></body></html>
